-- S374 SkyJuniper, 2026-10-12. Rule 8 ingest through execute_sql: INSERT-only, idempotent on slug,
-- each row logged to cpl_memory_log (actor SkyJuniperS374).
-- Rollback: delete from public.cpl_memory where author = 'SkyJuniperS374' and event_date = '2026-10-12';
insert into public.cpl_memory (slug, kind, org, title, summary, detail, plain, tags, source, related, status, author, event_date)
select x.slug, x.kind, 'cpl', x.title, x.summary, x.detail, x.plain, x.tags, x.source, '{}'::text[], x.status, 'SkyJuniperS374', date '2026-10-12'
from jsonb_to_recordset($json$[{"slug": "course-outline-objectives-share-slo-lead-in-2026-10-12", "kind": "pitfall", "title": "Outline objectives share the SLO lead-in", "summary": "S374 trial 38317539422: RCCD's outline prints Course Objectives then Student Learning Outcomes, each after 'Upon successful completion of the course...'; a lead-in rule read the objectives on all 12. kb/_course_outcomes_read.py reads the SLO area from the HTML; nested institutional outcomes are maps_to.", "detail": "The census SLO_HEADING accepts the lead-in as a heading. The HTML parser takes the subTitle 'Student Learning Outcomes' area and each top-level li; RCCD nests Critical Thinking / Communication Skills under an SLO, kept as maps_to. Filed trial pages are the test fixtures (tests/course_outcomes_read_test.py). KB note methodology-a-lead-in-sentence-is-not-a-section-heading. PR #2049.", "plain": "A course outline lists what the course teaches (objectives) and what students can do after it (learning outcomes), and both lists start with the same sentence. Our first reader grabbed the objectives on every page. It now looks for the section labeled Student Learning Outcomes.", "tags": ["course-outlines", "program-requirements-harvest", "pitfall"], "source": "PR #2049; docs/kb-notes/methodology-a-lead-in-sentence-is-not-a-section-heading.md", "status": "proposed"}, {"slug": "course-outcomes-read-rccd-slice1-2026-10-12", "kind": "milestone", "title": "RCCD SLO read, slice 1 of 4", "summary": "S374 run 38318152644 reads the SLOs of the 1,605 RCCD courses the loaded records name, in four slices; slice 1: 402 outlines, all 200, all parsed from HTML, 1,367 SLOs (1-10 a course, median 3). Table course_outcomes written (chatbox/supabase_course_outcomes.sql), not applied.", "detail": "Files land in kb/course_outcomes/rccd/read_38318152644_p<i>of4.json on claude/s374-course-outcomes-read (#2049). The load (kb/_course_outcomes_load.py, course-outcomes-load.yml on kb/course_outcomes/.load) keeps one row per college the outline's College line names (RIV, MOV, NOR); receipt kb/receipts/course_outcomes_<host>_<run>.json names every id and its delete. Governance map dismisses table, rpc and both workflows.", "plain": "We are copying the learning outcomes printed on about 1,600 Riverside, Moreno Valley and Norco course outlines. The first quarter is done: 402 courses, about three outcomes each. They will go into a public table once the table can be created.", "tags": ["course-outlines", "program-requirements-harvest", "riverside", "milestone"], "source": "PR #2049; run 38318152644", "status": "proposed"}, {"slug": "apply-migration-timeouts-2026-10-12", "kind": "risk", "title": "apply_migration timed out six times", "summary": "S374, 22:45-23:17Z: the Supabase MCP apply_migration timed out six times on the course_outcomes DDL with nothing reaching the database (no table, no ledger row, no lock, no open transaction; project ACTIVE_HEALTHY; execute_sql answering). The guard refuses DDL through execute_sql, so a session has no second path.", "detail": "S371 saw two such timeouts on Mesa's registry row and S372's third try took. Check to_regclass and supabase_migrations.schema_migrations after a timeout before retrying (a timeout is no proof of failure or of a lock). The DDL waits in chatbox/supabase_course_outcomes.sql; Sam can paste it in the SQL editor (precedent: Sheet 68 card 1, Pasted).", "plain": "The tool that creates database tables kept timing out tonight even though the database itself was fine, so the new outcomes table is written down but not created yet.", "tags": ["supabase", "pitfall", "course-outlines"], "source": "S374 session; lessons S374", "status": "proposed"}, {"slug": "mesa-nine-health-programs-four-tab-cap-2026-10-12", "kind": "fact", "title": "Mesa's nine: a four-tab cap", "summary": "S374 page reads 38318250175-38321027873: Mesa's nine health programs ARE in catalog 70's All Programs index (17541; 17589, 17590, 17626, 17687, 17688, 17700, 17708, 17709, 17727). Each shows six tabs with Requirements fifth; cq_children read four, so each scored 0.0. #2050 reads a Requirements tab first. Corrects mesa-loaded-displayed-2026-10-12's 'none is in the one section walked'.", "detail": "Tabs (Radiologic Technology 17900): Summary, Accreditation, Directed Clinical Practice Requirement, Admission Criteria, Requirements, Courses. Next: re-read Mesa, load, display; check Miramar's four not found (16779, 30512, 30532, 36254) for the same layout. Plan file kb/college_reads/mesa_health_programs.json narrates the seven reads.", "plain": "San Diego Mesa's health programs were in the catalog all along; their course lists sit on a fifth tab and our reader only opened four. The fix opens the Requirements tab first.", "tags": ["san-diego-mesa", "program-requirements-harvest", "curriqunet"], "source": "PR #2050", "status": "proposed"}, {"slug": "runner-pull-after-merge-fetches-history-2026-10-12", "kind": "pitfall", "title": "Runner pull after a merge is slow", "summary": "S374: a workflow that commits back with git pull --rebase on a one-commit checkout fetched main's whole history once the branch carried a merge of main (course outcomes slice 1: five minutes in the commit step). Land on the tip instead: fetch --depth=1, checkout FETCH_HEAD, lay the new files on, push; keep an artifact.", "detail": "course-outcomes-read.yml carries the pattern (#2049). Write the push target unquoted (HEAD:${{ github.ref_name }}): kb/_build_dependency_map.py reads it, and a quoted one drops the edge and fails the map's --check.", "plain": "When an automated job saves its results back to a branch that has been brought up to date with main, the simple way of saving downloads years of history first. Saving onto the latest version directly avoids it.", "tags": ["github-actions", "pitfall"], "source": "PR #2049", "status": "proposed"}]$json$::jsonb)
  as x(slug text, kind text, title text, summary text, detail text, plain text, tags text[], source text, status text)
on conflict (slug) do nothing;
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select m.id, 'SkyJuniperS374', 'create', 'checkpoint auto-write', to_jsonb(m) from public.cpl_memory m
where m.author = 'SkyJuniperS374' and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.actor = 'SkyJuniperS374');
select m.slug, m.kind, m.status, (select count(*) from public.cpl_memory_log l where l.memory_id = m.id) as logs
from public.cpl_memory m where m.author = 'SkyJuniperS374' order by m.created_at;
